(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"grammar-parts-of-speech-adverbs":{"title":"Parts of Speech: Adverbs","topic":"Grammar & Usage","questions":[{"id":"grammar-parts-of-speech-adverbs-q0001","version":2,"contentHash":"sha256:6479b6c4d653183dc7867923f593e006cc7fd27bf7ffbd2c2da51898fa16c729","question":"In \"Lena almost always reads very carefully,\" which choice lists only adverbs?","choices":["almost, always, very, carefully","Lena, reads, carefully","always, reads, very","almost, Lena, carefully"],"correct":0,"studyAid":{"definition":"Adverbs describe actions, adjectives, or other adverbs. They often answer questions like 'how?', 'when?', 'where?', or 'to what extent?'","example":"He ran quickly (adverb modifying verb). She is very tall (adverb modifying adjective). They arrived quite early (adverb modifying adverb).","strategyClue":"Test each word by asking if it describes an action or tells you the degree of something. If the word names a person, place, or thing, or identifies an action, exclude it from your list.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: almost, always, very, carefully. An adverb is a word that modifies a verb, an adjective, or another adverb. In this sentence, 'almost' and 'very' modify other adverbs, 'always' modifies a verb, and 'carefully' describes how Lena reads.","incorrect":["",{"choice":"Lena, reads, carefully","category":"noun and verb included","reason":"'Lena' is a noun (a person) and 'reads' is a verb (an action). Adverbs only describe verbs, adjectives, or other adverbs."},{"choice":"always, reads, very","category":"verb included","reason":"'Reads' is the action being performed, which makes it a verb, not an adverb. Always and very describe the action or the intensity."},{"choice":"almost, Lena, carefully","category":"noun included","reason":"'Lena' is the subject of the sentence, not an adverb. Adverbs tell us how, when, where, or to what extent something happens."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":1,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0002","version":2,"contentHash":"sha256:be6b9ac4cabf7add2a29ee78338b45cdf2b281ef14cc6017bbdf06b3196bc252","question":"Which adverb tells when the action happened?","choices":["The class met upstairs.","The class met yesterday.","The class met quietly.","The class almost met."],"correct":1,"studyAid":{"definition":"Adverbs of time tell us when an action takes place. They answer the specific question: 'When did this happen?'","example":"He arrived today. We left early. I will see you soon.","strategyClue":"Look at the bolded adverb in each sentence and ask yourself: 'Does this word describe a location, a way of doing something, or a specific time?' Only the time words answer 'when'.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The class met yesterday. 'Yesterday' is an adverb of time because it answers the question 'when' the meeting happened.","incorrect":[{"choice":"The class met upstairs.","category":"adverb of place","reason":"The word 'upstairs' describes *where* the action happened, not *when* it happened."},"",{"choice":"The class met quietly.","category":"adverb of manner","reason":"The word 'quietly' describes *how* the action happened, which is a different type of adverb."},{"choice":"The class almost met.","category":"adverb of degree","reason":"The word 'almost' describes *how much* or to what extent the action happened, rather than identifying a specific time."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":2,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0003","version":2,"contentHash":"sha256:72ca59ed7f0b6f427a8ebdcc3fb476a233da337d71e61ec447be59d75d6b6663","question":"Which adverb tells where?","choices":["The kite drifted upward.","The kite drifted slowly.","The kite drifted yesterday.","The kite nearly drifted."],"correct":0,"studyAid":{"definition":"Adverbs describe verbs, adjectives, or other adverbs. Adverbs of place specifically tell us where an action happens.","example":"He walked outside (where). She ran fast (how). They play here (where).","strategyClue":"Ask yourself, 'Does this word answer the question where?' If you can point to a location or direction, you have found an adverb of place.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The kite drifted upward. The word 'upward' describes the location or direction of the action, making it an adverb of place.","incorrect":["",{"choice":"The kite drifted slowly.","category":"adverb of manner","reason":"The word 'slowly' explains how the kite drifted, not where it went. This is an adverb of manner."},{"choice":"The kite drifted yesterday.","category":"adverb of time","reason":"The word 'yesterday' tells us when the drifting happened, not where. This is an adverb of time."},{"choice":"The kite nearly drifted.","category":"adverb of degree","reason":"The word 'nearly' describes the extent of the action, not the location. This is an adverb of degree."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":3,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0004","version":2,"contentHash":"sha256:9bbb873724eecc16658093544c8128d0d043bbb51dc8c5cf619f6e6c62f03b04","question":"Which sentence uses an adverb to modify an adjective?","choices":["The river moved quickly.","The very cold river moved past us.","The river outside froze.","The river froze yesterday."],"correct":1,"studyAid":{"definition":"An adverb can modify a verb, another adverb, or an adjective. When it modifies an adjective, it usually tells you 'how much' or 'to what extent' something is.","example":"He is very tired. (very modifies tired); It is quite hot today. (quite modifies hot).","strategyClue":"Look for a word that answers 'how much' or 'to what degree' about a descriptive word. Identify the adjective first, then see which word is adding extra information to it.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The very cold river moved past us. In this sentence, 'very' is an adverb that describes the intensity of the adjective 'cold', which modifies the noun 'river'.","incorrect":[{"choice":"The river moved quickly.","category":"adverb modifying verb","reason":"In this sentence, 'quickly' is an adverb that modifies the verb 'moved', telling us how the river moved rather than describing an adjective."},"",{"choice":"The river outside froze.","category":"adverb of place","reason":"The word 'outside' is an adverb of place modifying the verb 'froze' to tell us where the river was, not describing an adjective."},{"choice":"The river froze yesterday.","category":"adverb of time","reason":"The word 'yesterday' is an adverb that tells us when the action happened (modifying the verb 'froze'), not an adjective."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":4,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0005","version":2,"contentHash":"sha256:b11cda84e227e2d0b6e488c98bda73e30766319d8798d8fb8d621c2193d45140","question":"Which sentence uses an adverb to modify another adverb?","choices":["He spoke clearly.","He spoke very clearly.","He was very clear.","His clear speech helped."],"correct":1,"studyAid":{"definition":"An adverb is a word that modifies a verb, an adjective, or another adverb. Adverbs that modify other adverbs often describe the degree or intensity of the action.","example":"He ran quickly (adverb modifying verb). He ran very quickly (adverb modifying adverb). He is quite happy (adverb modifying adjective).","strategyClue":"Identify the word ending in '-ly' that describes an action, then look for a word that describes how or to what degree that '-ly' word is happening.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: He spoke very clearly. In this sentence, 'clearly' is an adverb describing how he spoke, and 'very' is another adverb that modifies the intensity of the word 'clearly'.","incorrect":[{"choice":"He spoke clearly.","category":"single adverb use","reason":"In this sentence, 'clearly' modifies the verb 'spoke', but there is no second adverb to modify 'clearly'. It only contains one adverb."},"",{"choice":"He was very clear.","category":"adverb modifying adjective","reason":"Here, 'very' is an adverb, but it modifies the adjective 'clear'. Adverbs can modify verbs, other adverbs, or adjectives, but this does not meet the requirement of modifying another adverb."},{"choice":"His clear speech helped.","category":"adjective usage","reason":"In this sentence, 'clear' is an adjective describing the noun 'speech'. It does not function as an adverb at all."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"grammar-parts-of-speech-adverbs","sequence":5,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0006","version":3,"contentHash":"sha256:d646ba0502f4314f039eb891630abe1413befd2f26ba09046e3ed02116031ab4","question":"Which word is NOT an adverb in this sentence: \"The team practiced outside yesterday\"?","choices":["team","outside","yesterday","practiced"],"correct":0,"studyAid":{"definition":"An adverb describes a verb by telling us how, when, or where something happens. A noun names a person, place, thing, or idea.","example":"He ran quickly (adverb: how). We arrived early (adverb: when). She sat there (adverb: where). The dog (noun) barked.","strategyClue":"Test each word by asking, 'Does this word tell me when, where, or how the action happened?' If a word names an object or a person, it belongs to a different part of speech.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: team. A noun identifies a person, place, thing, or animal. 'Team' is a noun because it refers to a group of people, whereas adverbs describe when, where, or how an action happens.","incorrect":["",{"choice":"outside","category":"adverb of place","reason":"The word 'outside' tells us WHERE the team practiced, which makes it an adverb. We are looking for the word that is NOT an adverb."},{"choice":"yesterday","category":"adverb of time","reason":"The word 'yesterday' tells us WHEN the action took place, which is exactly what an adverb does. It is not the word we are looking for."},{"choice":"practiced","category":"verb vs adverb","reason":"Actually, 'practiced' is a verb, not an adverb. However, since the question asks for the noun 'team', and 'practiced' is the action word in the sentence, it does not function as an adverb either."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-parts-of-speech-adverbs","sequence":6,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0007","version":2,"contentHash":"sha256:320091a067e9e02a3b51ee60b73565f0e8abaf84d76a9f89f794ce46b3477156","question":"Which adverb shows frequency?","choices":["rarely","nearby","gently","soon"],"correct":0,"studyAid":{"definition":"Adverbs of frequency tell us how often an action occurs, such as always, never, or sometimes.","example":"He always brushes his teeth. She rarely eats sweets. We never go there.","strategyClue":"Ask yourself: 'Does this word answer the question how often?' If you can fit the word into the phrase 'I do this [word]', it is likely a frequency adverb.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: rarely. Adverbs of frequency tell us how often something happens. 'Rarely' describes that an event happens only once in a while.","incorrect":["",{"choice":"nearby","category":"adverb of place","reason":"'Nearby' describes *where* something is, not how often it happens."},{"choice":"gently","category":"adverb of manner","reason":"'Gently' describes *how* an action is performed, rather than the frequency of the action."},{"choice":"soon","category":"adverb of time","reason":"'Soon' refers to *when* something will happen in the future, not how many times it happens."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":7,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0008","version":2,"contentHash":"sha256:6a0ee7f01ea71b3234f306c21beb21dcad4c344d9e2c26783de46e378b64609f","question":"Which sentence uses \"fast\" as an adverb?","choices":["The fast train arrived.","The train moved fast.","The fast was difficult.","Fast runners stretched."],"correct":1,"studyAid":{"definition":"An adverb is a word that describes or modifies a verb, an adjective, or another adverb by explaining how, when, where, or to what extent an action happens.","example":"He ran quickly (adverb modifying ran). He is a quick runner (adjective modifying runner).","strategyClue":"Look for the verb in the sentence. Ask yourself, 'Which word is telling me how the action in the verb is being done?'","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The train moved fast. An adverb modifies a verb, describing how an action is performed. Here, 'fast' describes how the train 'moved'.","incorrect":[{"choice":"The fast train arrived.","category":"adjective usage","reason":"In this sentence, 'fast' is an adjective because it describes the noun 'train' rather than describing how an action happened."},"",{"choice":"The fast was difficult.","category":"noun usage","reason":"Here, 'fast' is used as a noun representing a period of not eating. An adverb cannot be the subject of a sentence."},{"choice":"Fast runners stretched.","category":"adjective usage","reason":"In this sentence, 'fast' is an adjective because it tells us what kind of 'runners' they are, modifying the noun instead of a verb."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":8,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0009","version":2,"contentHash":"sha256:2ecb5d658201ddaf9e63664ef506e57518b7fcdb28a3a2ed3b810bfee534caf3","question":"Which adverb tells to what extent?","choices":["almost finished","finished outside","finished yesterday","finished neatly"],"correct":0,"studyAid":{"definition":"Adverbs of degree tell us about the intensity or extent of an action, adjective, or another adverb.","example":"He is very tired (extent of being tired), she almost left (extent of leaving), it is totally finished (degree of finish).","strategyClue":"Ask yourself if the adverb describes 'how much' or 'to what degree' the action is happening, rather than 'where', 'when', or 'how' it was done.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: almost finished. The word 'almost' is an adverb of degree. It explains the extent or intensity to which the action of finishing is happening.","incorrect":["",{"choice":"finished outside","category":"adverb of place","reason":"'Outside' tells us where the action happened, not to what extent."},{"choice":"finished yesterday","category":"adverb of time","reason":"'Yesterday' tells us when the action happened, not the degree to which it was completed."},{"choice":"finished neatly","category":"adverb of manner","reason":"'Neatly' describes how the action was performed, not the extent of the action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":9,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0010","version":2,"contentHash":"sha256:32b40f3ec91fd00baba519057daac4bffa1e45aaf05f002c5cb422c6481c4ba2","question":"Which sentence contains an adverb phrase?","choices":["We ate before the game.","We ate quickly.","We ate hot soup.","We ate dinner."],"correct":0,"studyAid":{"definition":"An adverb phrase is a group of words that works together to describe a verb, telling the reader when, where, or how an action takes place.","example":"We sat by the fire (where); The bus arrived at midnight (when); She ran with great speed (how).","strategyClue":"Look for a group of words that answers the question 'When?', 'Where?', or 'How?' the action happened. If the group of words starts with a preposition like 'before', 'at', 'in', or 'with', it is likely an adverb phrase.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: We ate before the game. An adverb phrase is a group of words that functions as an adverb, providing information about when, where, or how an action happened. 'Before the game' tells us when the action happened.","incorrect":["",{"choice":"We ate quickly.","category":"single word adverb","reason":"The word 'quickly' is an adverb, but it is just one word. An adverb phrase must be made up of a group of words, typically beginning with a preposition."},{"choice":"We ate hot soup.","category":"adjective phrase","reason":"'Hot' is an adjective describing the soup. This sentence contains an adjective, not a phrase that explains when, where, or how the action occurred."},{"choice":"We ate dinner.","category":"direct object noun","reason":"'Dinner' is a noun acting as the direct object. It tells us *what* was eaten, not *when* or *where* the eating happened."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-parts-of-speech-adverbs","sequence":10,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0011","version":3,"contentHash":"sha256:6b7317c9488566acc82dd253cbe33c47a7b5a77e3b521040697d0b5273a00be2","question":"Which ending is common for adverbs but not a guarantee?","choices":["-ly","-ness","-ful","-ment"],"correct":0,"studyAid":{"definition":"An adverb is a word that describes how, when, or where an action happens. Many, but not all, adverbs are formed by adding -ly to an adjective.","example":"soft (adjective) -> softly (adverb); happy (adjective) -> happily (adverb); fast (adverb) -> fast (no -ly added)","strategyClue":"Think about how you describe an action, like walking or speaking. Identify which of these endings is most frequently attached to adjectives to tell you the 'way' something is done.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: -ly. Adverbs are most commonly formed by adding -ly to the end of an adjective, such as changing 'quick' to 'quickly'.","incorrect":["",{"choice":"-ness","category":"noun suffix","reason":"The suffix -ness is used to change adjectives into nouns, such as 'kind' becoming 'kindness'. It does not create adverbs."},{"choice":"-ful","category":"adjective suffix","reason":"The suffix -ful is used to turn nouns into adjectives, like 'care' becoming 'careful'. It is a sign of an adjective, not an adverb."},{"choice":"-ment","category":"noun suffix","reason":"The suffix -ment is used to turn verbs into nouns, like 'enjoy' becoming 'enjoyment'. It is not a common ending for adverbs."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"grammar-parts-of-speech-adverbs","sequence":11,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0012","version":2,"contentHash":"sha256:8336315302b13eb064ecca0f7d072b2cdc2936ed9a715ee66599e54b31b73884","question":"Which sentence uses \"early\" as an adverb?","choices":["The early train left.","We left early.","Early birds sang.","The early bell rang."],"correct":1,"studyAid":{"definition":"Adjectives describe nouns (people, places, or things), while adverbs describe verbs (actions). Ask yourself if the word tells you about a thing or about an action.","example":"Adjective: The fast car. Adverb: He drove fast.","strategyClue":"Find the verb in the sentence first. If the target word explains when or how that action was done, it is an adverb. If it describes a person or object, it is an adjective.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: We left early. In this sentence, 'early' describes the action 'left,' making it an adverb because adverbs tell us how, when, or where an action happens.","incorrect":[{"choice":"The early train left.","category":"adjective usage","reason":"Here, 'early' describes the noun 'train.' Words that describe nouns are adjectives, not adverbs."},"",{"choice":"Early birds sang.","category":"adjective usage","reason":"In this sentence, 'early' tells us what kind of 'birds' they are. Since it describes a noun, it functions as an adjective."},{"choice":"The early bell rang.","category":"adjective usage","reason":"The word 'early' is modifying the noun 'bell.' Because it gives more information about a thing rather than an action, it is an adjective."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":12,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0013","version":2,"contentHash":"sha256:d8b61c7e0bf084cd1a3e031dcdb4cada2271dd27c102ba628bd258fb0f164968","question":"Which sentence uses an adverb of manner?","choices":["The artist painted carefully.","The artist painted yesterday.","The artist painted outside.","The artist almost painted."],"correct":0,"studyAid":{"definition":"An adverb of manner describes how someone does something. Many of these words end in the letters '-ly'.","example":"He ran quickly (how he ran). She spoke softly (how she spoke).","strategyClue":"Ask yourself, 'How did the subject do the action?' The word that answers that specific question is your adverb of manner.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The artist painted carefully. Adverbs of manner describe how an action is performed, and 'carefully' tells us how the artist painted.","incorrect":["",{"choice":"The artist painted yesterday.","category":"adverb of time","reason":"'Yesterday' tells us when the action happened, not how, making it an adverb of time rather than manner."},{"choice":"The artist painted outside.","category":"adverb of place","reason":"'Outside' tells us where the action happened, not how, making it an adverb of place rather than manner."},{"choice":"The artist almost painted.","category":"adverb of degree","reason":"'Almost' tells us the intensity or level of the action, not how the artist performed the task."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":13,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0014","version":2,"contentHash":"sha256:0b93bb3d7310e6f6ca1426b0f17c3fd48ab43eb8acd7998e052f3f27612c7954","question":"Which adverb best completes the sentence: \"The speaker talked ___ enough for the back row to hear\"?","choices":["loud","louder","loudly","loudness"],"correct":2,"studyAid":{"definition":"Adverbs are words that describe verbs (actions), adjectives, or other adverbs. They often end in '-ly'.","example":"He ran quickly (correct) vs He ran quick (incorrect); She sang beautifully (correct) vs She sang beautiful (incorrect).","strategyClue":"Look at the word being described in the sentence. If the word shows an action, ask yourself how the action is performed, and choose the word that describes that manner.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: loudly. Adverbs describe actions; since the speaker is 'talking', we need the adverb form 'loudly' to modify that verb.","incorrect":[{"choice":"loud","category":"adjective vs adverb","reason":"The word 'loud' is an adjective, which describes a noun. Because you are describing the action of talking, you need the adverb form 'loudly'."},{"choice":"louder","category":"comparative adjective","reason":"The word 'louder' compares two things. This sentence is describing the volume of the speaker in general, not comparing them to someone else."},"",{"choice":"loudness","category":"noun usage","reason":"'Loudness' is a noun (a thing), not a descriptor. You cannot 'talk loudness' because the sentence requires a word that explains how the talking was done."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":14,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0015","version":2,"contentHash":"sha256:9fdbb0d7429f8df9e95e9007a512f3a0e05370cb5544660c2f3e8ad1b6c97e49","question":"Which sentence places the adverb so the meaning is clearest?","choices":["Only Maya fed the fish after school.","Maya only fed the fish after school.","Maya fed only the fish after school.","Maya fed the fish only after school."],"correct":3,"studyAid":{"definition":"An adverb is a word that modifies a verb, adjective, or another adverb. Placing the adverb close to the specific word it describes keeps your meaning clear.","example":"I only ate a snack (I ate nothing else). I ate only a snack (I ate nothing else). I ate a snack only once (I ate it one time).","strategyClue":"Identify what specific part of the sentence you want to limit or describe. Move the word 'only' through different spots in the sentence and notice how the meaning changes each time.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Maya fed the fish only after school. Adverbs like 'only' should be placed right next to the word or phrase they modify. In this sentence, 'only' modifies 'after school,' showing specifically *when* the action happened.","incorrect":[{"choice":"Only Maya fed the fish after school.","category":"misplaced adverb (subject)","reason":"This places 'only' next to Maya, which means no one else fed the fish. This changes the meaning to focus on the person rather than the time."},{"choice":"Maya only fed the fish after school.","category":"misplaced adverb (verb)","reason":"By placing 'only' before 'fed,' it suggests that Maya didn't do anything else to the fish (like play with them) besides feeding them, which is not the intended meaning."},{"choice":"Maya fed only the fish after school.","category":"misplaced adverb (object)","reason":"This placement suggests that Maya fed the fish but did not feed any other pets, which shifts the focus away from the time of day."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":15,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-parts-of-speech-adverbs-q0016","version":2,"contentHash":"sha256:cb9c957550142021070394c7b6e34172b6e7457112dd1bfe44685fa286b57e6c","question":"The travelers spoke somewhat cautiously about whether or not they should cancel their tour to Europe. Which of the following pairs function as adverbs in the sentence?","choices":["should cancel","to Europe","their tour","somewhat cautiously"],"correct":3,"explanation":{"correct":"Answer: somewhat cautiously. 'Cautiously' is an adverb because it describes how the travelers spoke, and 'somewhat' is an adverb because it modifies the adverb 'cautiously' to tell us to what degree.","incorrect":[{"choice":"should cancel","reason":"\"should cancel\" does not match the tense, helping verb, or subject-verb pattern required here."},{"choice":"to Europe","category":"prepositional phrase","reason":"This phrase tells us where the tour is headed. It starts with the preposition 'to' followed by the noun 'Europe', so it functions as an adjective modifying 'tour'."},{"choice":"their tour","category":"noun phrase","reason":"This is the object of the verb. 'Their' is a possessive pronoun and 'tour' is the noun being discussed."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":16,"sourceFile":"Advanced-1_grammer and usage.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Adverbs are words that describe verbs, adjectives, or other adverbs, often explaining how, when, where, or to what extent an action happens.","example":"He ran quickly (describes verb); She is very happy (describes adjective); He spoke quite softly (describes adverb).","strategyClue":"Look for words that tell you 'how' something is done or 'how much' something is happening. Try removing words to see if they act as extra details about the action.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0017","version":3,"contentHash":"sha256:9f0b8e469bc982dbe7459457b560b756a029788a3e5265e376611f49a7ca1c82","question":"Which sentence is NOT written correctly?","choices":["Liz seldom uses the diction ary.","James drives more slowly than the average driver.","Gail drives cautious on icy roads.","Br axton never seems to make it to the bus stop on time."],"correct":2,"explanation":{"correct":"Answer: Gail drives cautious on icy roads. The word 'cautious' is an adjective, but the sentence requires an adverb like 'cautiously' to describe *how* Gail drives.","incorrect":[{"choice":"Liz seldom uses the diction ary.","category":"spelling error","reason":"While 'dictionary' is spelled correctly as one word in standard English, this sentence is grammatically sound regarding its use of the adverb 'seldom' to describe the verb 'uses'."},{"choice":"James drives more slowly than the average driver.","category":"adverb usage","reason":"The sentence uses 'slowly' correctly as an adverb to describe the action of driving. It is grammatically correct to compare adverbs with 'more'."},"",{"choice":"Br axton never seems to make it to the bus stop on time.","category":"sentence structure","reason":"Aside from the spacing error in the name, the sentence correctly uses 'never' and follows proper word order. It is a grammatically complete and functional sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":17,"sourceFile":"Advanced-2_grammer and usage.pdf","sourceQuestionNumber":6,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Adjectives describe nouns, while adverbs describe verbs. Many adverbs are formed by adding '-ly' to an adjective.","example":"He ran quick (incorrect) / He ran quickly (correct). She speaks soft (incorrect) / She speaks softly (correct).","strategyClue":"Identify the verb in each sentence and ask yourself: 'Does the word describe the person (noun) or how the action (verb) is performed?' If it describes the action, ensure the word is in adverb form.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0018","version":2,"contentHash":"sha256:a5a822aeb2a0e7518e34d6f4f5e25b3cf4863603a0c7ecdc5bc92125aaff117e","question":"What is the basic English pattern of the sentence below? The girl laughed and cried.","choices":["noun - verb - adverb","noun - verb - noun","noun - verb - verb","noun - link ing verb - adjective"],"correct":2,"explanation":{"correct":"Answer: noun - verb - verb. The sentence starts with the noun 'girl', followed by two action verbs, 'laughed' and 'cried', connected by the conjunction 'and'.","incorrect":[{"choice":"noun - verb - adverb","category":"incorrect word classification","reason":"The word 'cried' is an action verb, not an adverb. Adverbs usually describe how or when an action is performed, rather than being an action themselves."},{"choice":"noun - verb - noun","category":"incorrect word classification","reason":"The word 'cried' is not a noun. Nouns identify people, places, or things, while 'cried' identifies an action that the girl performed."},"",{"choice":"noun - link ing verb - adjective","category":"incorrect sentence structure","reason":"This pattern does not match because 'laughed' and 'cried' are active verbs, not linking verbs like 'is' or 'seems', and there are no adjectives describing the noun."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":18,"sourceFile":"Advanced-2_grammer and usage.pdf","sourceQuestionNumber":7,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A sentence pattern is the order of parts of speech, such as nouns (people/things) and verbs (actions).","example":"The dog barked (noun-verb), The bird flew and sang (noun-verb-verb), The cat ate the fish (noun-verb-noun).","strategyClue":"Label each word in the sentence one by one. Ask yourself if the word represents an object or a person (noun) or something that can be done (verb).","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0019","version":2,"contentHash":"sha256:deee545258b0b3f69354a42c2a57ef6ba0b88f1a7c35111382a2bb5b9cf70b23","question":"Choose the sentence using active voice.","choices":["The grades were assigned by the teacher.","The home was built by a reputable contractor.","Adam quickly finished his homework.","The winning goal was kicked by a freshman."],"correct":2,"explanation":{"correct":"Answer: Adam quickly finished his homework. This is active voice because the subject, Adam, is the one performing the action of finishing the homework.","incorrect":[{"choice":"The grades were assigned by the teacher.","category":"passive voice construction","reason":"This is passive voice because the subject, 'the grades', is receiving the action rather than doing it. The teacher is the one performing the action."},{"choice":"The home was built by a reputable contractor.","category":"passive voice construction","reason":"In this sentence, the home is the subject, but it is not building itself. Since the action is being done to the subject, it is passive voice."},"",{"choice":"The winning goal was kicked by a freshman.","category":"passive voice construction","reason":"The subject 'the winning goal' is receiving the action of being kicked. An active sentence would name the person doing the kicking as the subject."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":19,"sourceFile":"Advanced-3_grammer and usage.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Active voice occurs when the subject of a sentence performs the action. Passive voice occurs when the subject receives the action.","example":"Active: The cat chased the mouse. Passive: The mouse was chased by the cat.","strategyClue":"Identify the action verb and ask yourself: 'Who or what is actually doing this?' If the subject is the one doing it, it is active.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0020","version":3,"contentHash":"sha256:aa45a0ba6f219ced2892cbef49349d3ba0a2b8a31b8653f988df81d68b78c4a5","question":"Choose the best missing word. _________ the whistle sounded, and the train __ ______ left.","choices":["Quickly, highly","Anxiously, happily","Cautiously, tearfully","Suddenly, slowly"],"correct":3,"explanation":{"correct":"Answer: Suddenly, slowly. The adverbs 'suddenly' and 'slowly' are the best fit because 'suddenly' describes the surprising nature of the whistle, and 'slowly' describes how a large, heavy train usually begins to depart.","incorrect":[{"choice":"Quickly, highly","category":"inappropriate adverb choice","reason":"While 'quickly' could fit the whistle, 'highly' does not describe how a train moves. 'Highly' is used for intensity, not speed or motion."},{"choice":"Anxiously, happily","category":"mismatched adverb meaning","reason":"These adverbs describe feelings or emotions. Trains are machines and do not have feelings, so these words do not make sense in this context."},{"choice":"Cautiously, tearfully","category":"spelling and usage","reason":"The word 'cautiously' contains a typo (it should be one word: 'cautiously'), and 'tearfully' describes a human crying, which does not fit a train's departure."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":20,"sourceFile":"Advanced-4_grammer and usage.pdf","sourceQuestionNumber":6,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Adverbs are words that describe how, when, where, or to what extent an action happens. They often end in -ly and tell us more about the verb in the sentence.","example":"The dog barked loudly. She arrived quickly. The train moved slowly.","strategyClue":"Ask yourself, 'What kind of word makes sense for a train?' Try replacing the blank with words that describe speed or movement, and eliminate words that describe human emotions or feelings.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-parts-of-speech-adverbs-q0021","version":2,"contentHash":"sha256:9b7e27dbf31289e5575fe826d1b906a44eefef28689cfeca442353ba0c112dd8","question":"The travelers spoke somewhat cautiously about whether or not they should cancel their tour to Europe. Which of the following pairs function as adverbs in the sentence above?","choices":["should cancel","to Europe","their tour","somewhat cautiously"],"correct":3,"explanation":{"correct":"Answer: somewhat cautiously. Adverbs are words that modify verbs, adjectives, or other adverbs, often describing how or to what degree an action is performed.","incorrect":[{"choice":"should cancel","reason":"\"should cancel\" does not match the tense, helping verb, or subject-verb pattern required here."},{"choice":"to Europe","category":"prepositional phrase","reason":"This is a prepositional phrase that describes where the tour is going, not how an action is being performed."},{"choice":"their tour","category":"noun phrase","reason":"This is a noun phrase that functions as the object of the verb. It represents a thing, whereas adverbs describe qualities of actions."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":21,"sourceFile":"Advanced-6_grammer and usage.pdf","sourceQuestionNumber":6,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Adverbs describe verbs, adjectives, or other adverbs by answering questions like 'how,' 'when,' 'where,' or 'to what extent.' Many adverbs end in '-ly.'","example":"He walked quickly (describes how); The music was very loud (describes to what extent); She sang beautifully (describes how).","strategyClue":"Look for words that tell you more about the action verb in the sentence. Ask yourself, 'In what manner is the action being done?' and look for those descriptive modifiers.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0022","version":3,"contentHash":"sha256:27b3f5d909aa2e2fb08df93ac455c0baf1b35f8ae51cfe5de2b564791a20799e","question":"Choose the best missing wordor words. My sister ________ cleaned the cage.","choices":["quicker","more quick","quickly","quicklier"],"correct":2,"explanation":{"correct":"Answer: quickly. We use an adverb to describe how an action (cleaned) is performed. 'Quickly' is the correct adverb form used to modify the verb.","incorrect":[{"choice":"quicker","category":"comparative adjective error","reason":"'Quicker' is used to compare two things, not to describe the action of cleaning. Use the adverb 'quickly' to show how the cleaning happened."},{"choice":"more quick","category":"incorrect adverb formation","reason":"We do not use 'more' to create adverbs from 'quick'. The proper adverb form is 'quickly' by adding '-ly' to the adjective."},"",{"choice":"quicklier","category":"non-existent word","reason":"'Quicklier' is not a real word in English. The adverb form of 'quick' is simply 'quickly'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":22,"sourceFile":"Basic-1_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Adverbs are words that describe actions (verbs). Most adverbs that describe how something is done are made by adding '-ly' to the end of an adjective.","example":"He ran fast (adverb); She sang loudly (adverb). Correct: He walked slowly. Incorrect: He walked slow.","strategyClue":"Look at the verb 'cleaned' and ask, 'How was the cage cleaned?' When you are describing an action, look for the word that tells you the manner of the action, usually ending in -ly.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-parts-of-speech-adverbs-q0023","version":2,"contentHash":"sha256:2857a94b3f2d283055855c66ac5c45654ef1abbd0f0d1599825d9cf80f17b888","question":"In the sentence below, which adverb tells where? Yesterday, the class went outside quickly and quietly.","choices":["Yesterday","outside","quickly","quietly"],"correct":1,"explanation":{"correct":"Answer: outside. Adverbs of place describe where an action takes place. In this sentence, 'outside' tells us the location where the class went.","incorrect":[{"choice":"Yesterday","category":"adverb of time","reason":"The word 'Yesterday' tells us *when* the action happened, not *where*. It is an adverb of time."},"",{"choice":"quickly","category":"adverb of manner","reason":"The word 'quickly' describes *how* the class moved. Adverbs ending in -ly often describe the manner in which an action is performed."},{"choice":"quietly","category":"adverb of manner","reason":"Like 'quickly', 'quietly' describes the manner of the action, explaining *how* the students behaved while they were moving."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":23,"sourceFile":"Basic-6_grammer and usage.pdf","sourceQuestionNumber":1,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Adverbs of place tell us where an action happens, while adverbs of manner tell us how, and adverbs of time tell us when.","example":"Place: We played here. Manner: He ran fast. Time: We left early.","strategyClue":"Ask yourself if each word tells you about the timing, the way something was done, or the location of the action. Only one of these options describes a physical place.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0024","version":4,"contentHash":"sha256:25326904ec53c1713a756bb817350a09b5660b5672c4da4e065a0ce6f0db18e2","question":"Choose the correct missing word. Janet ________ appeared in the room.","choices":["suddenly","sudden","sooner","soonest"],"correct":0,"explanation":{"correct":"Answer: suddenly. This sentence describes how Janet appeared, so you need an adverb. Adverbs that describe actions often end in '-ly' to show the manner in which something happened.","incorrect":["",{"choice":"sudden","category":"adjective vs adverb","reason":"'Sudden' is an adjective used to describe nouns, like 'a sudden noise.' You need an adverb here to describe the action of appearing."},{"choice":"sooner","category":"incorrect comparative adjective","reason":"'Sooner' is a comparative word used to compare two different times. It does not fit the sentence structure which requires a descriptive adverb of manner."},{"choice":"soonest","category":"incorrect superlative adjective","reason":"'Soonest' is a superlative word used to compare three or more times. It is not an adverb of manner and doesn't fit the sentence's meaning."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":24,"sourceFile":"Proficient-1_grammer and usage.pdf","sourceQuestionNumber":2,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"An adverb is a word that modifies a verb, an adjective, or another adverb. Many adverbs are formed by adding '-ly' to the end of an adjective.","example":"Quick (adj) becomes Quickly (adv); Soft (adj) becomes Softly (adv).","strategyClue":"Look at the word appearing after the blank. If the word describes how an action is being performed, try adding '-ly' to the root word to create an adverb.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-parts-of-speech-adverbs-q0025","version":3,"contentHash":"sha256:d0715cec43984e0dfe24e81edb50b2b5da7e1e14d45f00abb7d9a25280991c48","question":"Choose the best missing word. The detective quickly _________ down the stairs, out the door, and escap ed through the alley.","choices":["race","racing","raced","races"],"correct":2,"explanation":{"correct":"Answer: raced. The sentence uses past tense verbs like 'escaped', so all actions in the sequence must also be in the past tense to keep the sentence consistent.","incorrect":[{"choice":"race","category":"incorrect verb tense","reason":"Using 'race' creates a tense clash because the sentence is describing a completed event in the past, not something happening right now."},{"choice":"racing","category":"missing helping verb","reason":"'Racing' needs a helping verb like 'was' to show past action. Without one, it does not fit the pattern of the other past-tense verbs in the sentence."},"",{"choice":"races","category":"present tense error","reason":"'Races' is present tense, which does not match the past tense verb 'escaped' used later in the same sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":25,"sourceFile":"Proficient-3_grammer and usage.pdf","sourceQuestionNumber":7,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Verbs in a sentence should stay in the same tense to show that actions happen at the same time or in the same period.","example":"Correct: He jumped and ran. Incorrect: He jumped and run.","strategyClue":"Look for the other verbs in the sentence. Identify if they end in -ed or describe a past action, then choose the option that matches that same timing.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-parts-of-speech-adverbs-q0026","version":2,"contentHash":"sha256:32153d8acea71ec794c9d5886d23390eaf19fec46c0d9e3b100f167fb53a043a","question":"Choose the best word to complete the sentence. Juan earned the ________ highest grade on the test.","choices":["mo stly","rather","very","especially"],"correct":2,"explanation":{"correct":"Answer: very. We use 'very' to intensify a superlative adjective like 'highest'. It acts as an adverb modifying the superlative to emphasize the degree of success.","incorrect":[{"choice":"mo stly","category":"incorrect spelling","reason":"The word is spelled incorrectly with a space. Even as 'mostly', it does not fit the structure to describe a specific rank like 'highest grade'."},{"choice":"rather","category":"inappropriate adverb usage","reason":"While 'rather' can be an intensifier, it is usually used with adjectives, not superlatives like 'highest'. 'Very' is the standard choice to emphasize a superlative."},"",{"choice":"especially","category":"improper sentence structure","reason":"Using 'especially' here is grammatically awkward. It functions better when modifying verbs or describing an event rather than directly preceding a superlative adjective."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":26,"sourceFile":"Proficient-4_grammer and usage.pdf","sourceQuestionNumber":6,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"To emphasize a superlative (a word ending in -est or starting with 'most'), use the intensifier 'very'.","example":"He is the very best student. She got the very smallest slice.","strategyClue":"Test each word by reading the sentence aloud. Ask yourself if the word sounds natural as a way to add emphasis to the superlative adjective 'highest'.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0027","version":4,"contentHash":"sha256:887aae8641029a70de0db3183ba40aec8f9a4417b7ab429e13f1604ea7388567","question":"Which of the following is NOT an adverbial clause?","choices":["After we went to the movie,","After school last night,","After we climbed the mountain,","After we completedour unit exam,"],"correct":1,"explanation":{"correct":"Answer: After school last night,. An adverbial clause must contain both a subject and a verb. This option is a prepositional phrase because it lacks a verb.","incorrect":[{"choice":"After we went to the movie,","category":"contains subject and verb","reason":"This is an adverbial clause because it has a subject ('we') and a verb ('went'), meaning it functions as a subordinate clause."},"",{"choice":"After we climbed the mountain,","category":"contains subject and verb","reason":"This is an adverbial clause because it contains the subject 'we' and the action verb 'climbed', making it a complete clause."},{"choice":"After we completedour unit exam,","category":"contains subject and verb","reason":"Despite the typo, this contains the subject 'we' and the verb 'completed', which qualifies it as an adverbial clause."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":27,"sourceFile":"Advanced-1_Writing strategies_Application_Style.pdf","sourceQuestionNumber":6,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"An adverbial clause is a group of words that functions as an adverb and must contain both a subject and a verb.","example":"Adverbial clause: 'While I ran' (subject: I, verb: ran). Prepositional phrase: 'During the race' (no verb).","strategyClue":"Look at each phrase and identify if there is a clear subject performing an action verb. If a phrase is missing a verb, it cannot be a clause.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0028","version":2,"contentHash":"sha256:79eefda02afb5c68131317ba3be3cb54019b996b2b7b7b6c537e66339a3d385f","question":"Which sentence shows a superlative adverb?","choices":["Beth completed the process very efficiently.","Sally works more quickly than most.","Gerald reads quietly in the window seat.","Outof the entire class, Grace works most carefully."],"correct":3,"explanation":{"correct":"Answer: Out of the entire class, Grace works most carefully. The word 'most' is used with the adverb 'carefully' to compare one person's actions to the entire group, which is the definition of a superlative.","incorrect":[{"choice":"Beth completed the process very efficiently.","category":"simple adverb","reason":"The word 'very' is just an intensifier for the adverb 'efficiently.' It does not compare Beth to anyone else."},{"choice":"Sally works more quickly than most.","category":"comparative adverb","reason":"This uses 'more,' which is a comparative adverb used for comparing two things or groups. Superlatives are for three or more items or an entire group."},{"choice":"Gerald reads quietly in the window seat.","category":"positive adverb","reason":"The word 'quietly' is a simple adverb describing how Gerald reads. It is not comparing his reading speed or quality to anyone else."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":28,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":22,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A superlative adverb describes an action to the highest or lowest degree possible, usually involving a group of three or more.","example":"He runs fast (simple), he runs faster than me (comparative), he runs fastest of all (superlative).","strategyClue":"Look for words like 'most' or adjectives ending in '-est' that suggest the action is being compared against an entire group rather than just one other person.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0029","version":2,"contentHash":"sha256:53d8df053819babf0d67f4f44e75dc2d7e6be6f8b8bf0f8d26d8c90148aab973","question":"Read the sentence below. Ted is the captain of the team. Of the team is a prepositional phrase being used as a(n):","choices":["adjective","adverb","noun","verb"],"correct":0,"explanation":{"correct":"Answer: adjective. Prepositional phrases act as adjectives when they modify or describe a noun—in this case, 'the captain'.","incorrect":["",{"choice":"adverb","category":"adverbial function error","reason":"Adverbial phrases describe when, where, or how an action happens. This phrase tells us *which* captain, rather than describing the verb."},{"choice":"noun","category":"noun phrase confusion","reason":"A noun phrase acts as the subject or object of a sentence. This phrase cannot act as the subject because it begins with the preposition 'of'."},{"choice":"verb","category":"verb function error","reason":"Verbs describe actions or states of being. This phrase does not show an action or state; it provides extra detail about the noun."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":29,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":40,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A prepositional phrase acts as an adjective when it modifies a noun to tell us which one or what kind.","example":"The book on the shelf (which book?), The girl with the red hat (which girl?), A man of courage (what kind of man?)","strategyClue":"Look at the word immediately before the prepositional phrase. If that word is a noun, ask if the phrase is describing it. If the phrase answers 'which one' or 'what kind', it is acting as an adjective.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0030","version":3,"contentHash":"sha256:2b5880edc3b4cf7c2f0743407dadcb651c9ba90b1a26a34c86cd9d40c1d3cb1b","question":"Which sentence does not have an adverb?","choices":["Jake quickly ran back inside.","Please make sure the door is completely closed.","Masha rudely interrupted the teacher.","We have onions and tomatoes in our garden."],"correct":3,"explanation":{"correct":"Answer: We have onions and tomatoes in our garden. This sentence contains nouns, verbs, and prepositions, but it does not contain a word that describes how, when, or where an action is performed.","incorrect":[{"choice":"Jake quickly ran back inside.","category":"adverb present","reason":"The word 'quickly' is an adverb because it describes how Jake ran. Since the question asks for the sentence without an adverb, this is incorrect."},{"choice":"Please make sure the door is completely closed.","category":"adverb present","reason":"The word 'completely' is an adverb that describes the extent to which the door is closed. Because it contains an adverb, this sentence is not the correct choice."},{"choice":"Masha rudely interrupted the teacher.","category":"adverb present","reason":"The word 'rudely' is an adverb describing the manner in which Masha interrupted. Therefore, this sentence does contain an adverb."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":30,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":3,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"An adverb is a word that describes a verb, an adjective, or another adverb. They often tell us how, when, where, or to what extent something happens, and many end in -ly.","example":"He walked slowly (how), she arrived yesterday (when), they played there (where).","strategyClue":"Look for words that describe the action in the sentence. If a word tells you 'how' an action is done, it is an adverb. If every word in the sentence just names people, objects, or actions, it likely has no adverb.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0031","version":2,"contentHash":"sha256:56715d15a1d4139a1182d2477a18afd9588e9c194cfd57e2643c1eb2a214a34b","question":"Which of the following details is an adverb that expresses where?","choices":["normally","carefully","nearby","today"],"correct":2,"explanation":{"correct":"Answer: nearby. The word 'nearby' is an adverb of place because it describes the location where an action takes place.","incorrect":[{"choice":"normally","category":"adverb of frequency","reason":"This word describes how often something happens, not where it happens."},{"choice":"carefully","category":"adverb of manner","reason":"This word explains the way or manner in which an action is performed, rather than the location."},"",{"choice":"today","category":"adverb of time","reason":"This word tells us when an action occurs, which identifies it as an adverb of time, not place."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":31,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":6,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Adverbs of place tell us where an action happens, answering the question 'where?'","example":"The dog ran outside. (Where? Outside.) He played nearby. (Where? Nearby.)","strategyClue":"Ask yourself if the word describes a location, a time, or how something is done. Only location words answer the question 'where?'.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0032","version":2,"contentHash":"sha256:09c3b089f1a3e24f6a3a8d2db7efc4b6ae431a0a36ea5eae8f17628689a31d25","question":"What is the pattern of this sentence? Mallory clapped happily.","choices":["noun – linking verb – adjective","noun – verb – adverb","noun – linking verb – adverb","noun – verb – adjective"],"correct":1,"explanation":{"correct":"Answer: noun – verb – adverb. 'Mallory' is the person (noun), 'clapped' is the action she performed (verb), and 'happily' describes how she clapped (adverb).","incorrect":[{"choice":"noun – linking verb – adjective","category":"verb and modifier mismatch","reason":"'Clapped' is an action verb, not a linking verb like 'is' or 'seems', and 'happily' is an adverb describing the action, not an adjective describing the noun."},"",{"choice":"noun – linking verb – adverb","category":"incorrect verb type","reason":"'Clapped' shows physical movement and action, so it is an action verb, not a linking verb. Linking verbs connect subjects to descriptions."},{"choice":"noun – verb – adjective","category":"adjective versus adverb","reason":"'Happily' is an adverb because it modifies the verb 'clapped'. Adjectives are used to describe nouns, like 'happy girl', not to describe actions."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":32,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":28,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A sentence pattern is the order of parts of speech. Adverbs describe how, when, or where an action verb is done, while adjectives describe nouns.","example":"He ran (verb) quickly (adverb). The sky (noun) is (linking verb) blue (adjective).","strategyClue":"Ask yourself if the final word describes the action (how it was done) or the person (what they are like). Then, identify if the verb shows action or just connects ideas.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0033","version":2,"contentHash":"sha256:c0508ab512af8398a215ab6bbaa752e042342f223efcf736894658c6785c74bf","question":"Which choice is an adverb?","choices":["strange","calmly","unclear","sudden"],"correct":1,"explanation":{"correct":"Answer: calmly. Adverbs often describe how an action is performed and frequently end in '-ly'. In this case, 'calmly' tells us the manner in which someone did something.","incorrect":[{"choice":"strange","category":"adjective usage","reason":"The word 'strange' is an adjective used to describe a person, place, or thing. It does not describe how an action happens."},"",{"choice":"unclear","category":"adjective usage","reason":"'Unclear' is an adjective because it describes a noun, like 'an unclear instruction.' It does not explain how a verb was carried out."},{"choice":"sudden","category":"adjective usage","reason":"'Sudden' is an adjective, as in 'a sudden noise.' To turn this into an adverb that describes an action, you would need to change it to 'suddenly'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":33,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":34,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"An adverb is a word that describes a verb, an adjective, or another adverb. Many adverbs end in the letters '-ly'.","example":"He walked slowly (adverb). It was a slow walk (adjective). She smiled happily (adverb). It was a happy smile (adjective).","strategyClue":"Try adding a verb after each word. If you can perform the word as an action in a specific way, like 'walked ______' or 'spoke ______', it is likely an adverb.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0034","version":2,"contentHash":"sha256:782e34ad9951d4645fc79485ea2205fe19686b4c714f1e50744fc8d6e2ff69f8","question":"Which word would best describe how the old man hobbled down the street? The old man ______________ hobbled down the street.","choices":["exactly","quickly","foolishly","slowly"],"correct":3,"explanation":{"correct":"Answer: slowly. Adverbs describe the action of the verb. Since the man is 'hobbling,' he is moving with difficulty or at a low speed, making 'slowly' the most logical description.","incorrect":[{"choice":"exactly","category":"inappropriate adverb usage","reason":"The word 'exactly' describes precision, not movement. It does not explain the way someone walks down a street."},{"choice":"quickly","category":"contrary adverb meaning","reason":"Hobbling implies moving with difficulty or pain. 'Quickly' suggests speed, which contradicts the slow, hindered nature of a limp or hobble."},{"choice":"foolishly","category":"unrelated adverbial description","reason":"While 'foolishly' is an adverb, it describes an attitude or a decision. It does not describe the physical speed or manner of walking down a street."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":34,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":9,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"An adverb is a word that modifies a verb, telling us how, when, where, or to what extent an action happens.","example":"He walked quickly (speed). She spoke loudly (volume). They laughed happily (manner).","strategyClue":"Look at the verb 'hobbled' and imagine the movement. Ask yourself, 'What kind of movement is a hobble?' and choose the word that describes that specific pace.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0035","version":2,"contentHash":"sha256:5cc511efd1485c43cc641628e5310532a0817547ce1e74206d577cdf1562089d","question":"Which word would best describe how the wind blew across the field? The wind _____ blew across the field ripping the plants from the ground.","choices":["calmly","quietly","wildly","lazily"],"correct":2,"explanation":{"correct":"Answer: wildly. The context clue 'ripping the plants from the ground' shows the wind was powerful and destructive, making 'wildly' the best fit to describe such a strong action.","incorrect":[{"choice":"calmly","category":"opposite meaning","reason":"If the wind were blowing calmly, it would not be strong enough to rip plants from the ground. This word describes a gentle, peaceful movement."},{"choice":"quietly","category":"mismatched action","reason":"Quietly describes a sound level, not the force of the wind. A force strong enough to uproot plants is usually loud and violent, not quiet."},"",{"choice":"lazily","category":"mismatched intensity","reason":"Lazily implies a slow, sleepy motion. A wind that is lazily blowing would not have the intensity needed to destroy or rip plants."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":35,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":9,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"An adverb is a word that describes how an action is done. Choosing the right adverb helps the reader visualize the intensity and mood of the scene.","example":"He walked slowly (gentle). He raced wildly (energetic). The rain fell softly (calm). The rain hammered violently (strong).","strategyClue":"Look at the rest of the sentence for action clues. If the action mentioned is destructive or forceful, look for an adverb that matches that high level of energy.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0036","version":2,"contentHash":"sha256:064ccc6b78c8788f52cc727476469a66556f46424763a2fae0fb50138f1d2106","question":"Which is the basic English pattern of the sentence? The flower is fragrant.","choices":["noun-linking verb-adjective","noun-linking verb-noun","noun- verb-noun","noun-verb-adverb"],"correct":0,"explanation":{"correct":"Answer: noun-linking verb-adjective. The word 'flower' is a noun, 'is' is a linking verb that connects the subject to a description, and 'fragrant' is an adjective that describes the flower.","incorrect":["",{"choice":"noun-linking verb-noun","category":"incorrect sentence part","reason":"While 'flower' and 'is' are correct, 'fragrant' is not a noun. Nouns name things, but 'fragrant' is a word that describes how something smells."},{"choice":"noun- verb-noun","category":"incorrect sentence structure","reason":"This pattern does not match the sentence. 'Fragrant' is an adjective used to describe the subject, not a noun acting as a second object."},{"choice":"noun-verb-adverb","category":"incorrect word class","reason":"The word 'fragrant' is an adjective, not an adverb. Adverbs usually describe actions, while adjectives describe nouns."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":36,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":28,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A sentence follows a pattern based on the role each word plays: a noun names a thing, a linking verb connects a subject to a description, and an adjective describes a noun.","example":"The dog (noun) is (linking verb) hungry (adjective). The sky (noun) is (linking verb) blue (adjective).","strategyClue":"Ask yourself what each word does: Does it name something, show a state of being, or describe a quality? Identify the part of speech for each word in order to match the pattern.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0037","version":2,"contentHash":"sha256:7b914c92e1f00a2c7846e6b1432da49e2ec121fe7c0e0322247d0ea4d83d6523","question":"Read the sentence below. That is Sharon’s book. Sharon’s is what partof speech?","choices":["noun","verb","adjective","adverb"],"correct":2,"explanation":{"correct":"Answer: adjective. In this sentence, 'Sharon’s' functions as a possessive adjective because it modifies the noun 'book' by telling us who owns it.","incorrect":[{"choice":"noun","category":"noun vs adjective","reason":"While Sharon is a noun, when it is used as 'Sharon's' to describe possession, it acts as an adjective that modifies the noun 'book'."},{"choice":"verb","category":"verb vs adjective","reason":"A verb describes an action or state of being. 'Sharon’s' does not show an action here; it shows ownership of an object."},"",{"choice":"adverb","category":"adverb vs adjective","reason":"Adverbs usually describe verbs, adjectives, or other adverbs (often ending in -ly). 'Sharon’s' describes the book, not how it is being used."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":37,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":31,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A possessive noun used before another noun acts like an adjective because it tells us which person or thing owns the object.","example":"Tom's hat (adjective), The dog's bowl (adjective).","strategyClue":"Look at the word following the possessive noun. If it is a noun, ask yourself: 'Whose noun is it?' Since the word answers 'whose', it is acting as an adjective.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0038","version":2,"contentHash":"sha256:6d2b3e586d7312892268dade43397064c35544b8cc54b707bc8530ad852844a4","question":"Which word would best describe how the farmer drove? The farmer _____ drove around the doe and her baby lying in the grass so he wouldn’t scare them.","choices":["cheerfully","carefully","quickly","hotly"],"correct":1,"explanation":{"correct":"Answer: carefully. This word is an adverb that describes the action of driving. Since the farmer wanted to avoid scaring the animals, driving with care is the most logical choice.","incorrect":[{"choice":"cheerfully","category":"mismatched context","reason":"While 'cheerfully' is an adverb, driving happily doesn't explain why he drove in a specific way to avoid scaring the animals. 'Carefully' describes the safety required for this situation."},"",{"choice":"quickly","category":"mismatched context","reason":"Driving 'quickly' near a doe and her baby might startle them. The context of the sentence focuses on avoiding a scare, making 'carefully' the better choice."},{"choice":"hotly","category":"incorrect word usage","reason":"'Hotly' is usually used for arguments or weather, not for describing the speed or manner of driving a vehicle."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":38,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":9,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Adverbs describe actions by telling us how, when, or where something happens. Most adverbs that tell 'how' end in -ly.","example":"He walked slowly (correct) vs. He walked slow (incorrect); She sang beautifully (correct) vs. She sang beautiful (incorrect).","strategyClue":"Look at the result of the action described in the sentence. Ask yourself what type of movement would prevent the consequence mentioned in the final clause.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0039","version":2,"contentHash":"sha256:bedf10860fb2930ddd1a45155779cc5df437c19f532c928a394c365a12f04107","question":"What is the pattern of this sentence? The light shone brightly.","choices":["noun – linking verb – adjective","noun – verb – adverb","noun – verb – adjective","noun – verb – noun"],"correct":1,"explanation":{"correct":"Answer: noun – verb – adverb. 'The light' is the noun acting as the subject, 'shone' is the action verb, and 'brightly' is the adverb describing how the light shone.","incorrect":[{"choice":"noun – linking verb – adjective","category":"incorrect sentence structure","reason":"A linking verb connects a noun to an adjective (like 'The light was bright'). 'Shone' is an action verb, not a linking verb."},"",{"choice":"noun – verb – adjective","category":"adverb vs adjective","reason":"An adjective describes a noun, but 'brightly' describes how the action happened. Words ending in -ly that describe actions are adverbs, not adjectives."},{"choice":"noun – verb – noun","category":"missing direct object","reason":"A noun after a verb is usually a direct object receiving the action. 'Brightly' is not a noun because it does not name a person, place, or thing."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sequence":39,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":28,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A sentence pattern is the order of parts of speech. Adverbs describe verbs, while adjectives describe nouns.","example":"He ran quickly (adverb), He is quick (adjective), He ate lunch (noun).","strategyClue":"Identify the word describing the action. If it explains 'how' the verb happened, it is an adverb. If it names a person, place, or thing, it is a noun.","link":"","linkText":""}},{"id":"grammar-parts-of-speech-adverbs-q0040","version":2,"contentHash":"sha256:81fc0da32ca7a80d54773204e1058fba2795ab9ba69061e860cf052c866a013b","question":"What is the correct order of adverbs in the sentence below? The huge lion hungrily and stealthily stalked the brown, aloof rabbit.","choices":["huge, aloof","hungrily and stealthily","stealthily and hungrily","brown aloof"],"correct":1,"explanation":{"correct":"Answer: hungrily and stealthily. Adverbs describe how an action is performed. In this sentence, the lion stalked in a 'hungrily' and 'stealthily' manner, making these the correct adverbs to modify the verb 'stalked'.","incorrect":[{"choice":"huge, aloof","reason":"\"huge, aloof\" does not match the tense, helping verb, or subject-verb pattern required here."},"",{"choice":"stealthily and hungrily","category":"stylistic preference","reason":"While this is grammatically acceptable, 'hungrily and stealthily' follows the established order in the original sentence provided, which flows more naturally by placing the primary motive before the method."},{"choice":"brown aloof","category":"adjective misuse","reason":"'Brown' is a color and 'aloof' is a personality trait; both are adjectives describing the rabbit. They cannot describe the action of stalking, which requires an adverb."}]},"studyAid":{"definition":"Adverbs are words that modify verbs, adjectives, or other adverbs. They often end in '-ly' and explain how, when, where, or to what extent an action happens.","example":"He walked slowly (adverb). The cat purred loudly (adverb). She is very kind (adverb modifying adjective).","strategyClue":"Identify the main verb in the sentence (the action) and ask yourself 'how' that action is being done. Look for the words that describe the manner of the action rather than the description of the people or things involved.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-parts-of-speech-adverbs","sourceFile":"Advanced Quiz 3_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":40,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
